        this.selections.set(sourcePath, selection)

        return selection
    }

    setSelection(sourcePath: string, selection: AgentSelectionState) {
        this.selections.set(sourcePath, selection)
    }

    clearSelection(sourcePath: string) {
        this.selections.delete(sourcePath)
    }

    clear() {
        this.selections.clear()
    }
}

